#!/usr/bin/env python3
# Intended for Dev/Test environments only.
#
# api-verify script for module __MOD__ — generated by the api-verify skill
# (.claude/skills/api-verify/SKILL.md). Regenerate it; never hand-edit it.
#
# It holds the module's published api-docs (plan.api_docs) to its API document
# (plan.api_spec, OpenAPI 3.1) by calling the RUNNING service end-to-end in
# dependency order. Every path is read through scripts/gov-module.py (the v7
# consumer contract); every response shape and error code is read from the API
# document at run time, never typed here.
#
# It never calls PUT / PATCH / DELETE, never writes to the database or a host
# system directly, never reaches a real host Approval API, and sends only
# synthetic, run-namespaced values.
#
#   python3 test___mod___apis.py --env dev [--base-url URL] [--namespace RUN-x]
#                                [--approval-stub-url URL] [--log-file PATH]
#
# Exit code: 0 = every asserted call passed · 1 = an asserted failure ·
#            2 = refused to run (target not confirmed Dev/Test, inputs missing).
from __future__ import annotations

import argparse
import datetime as dt
import json
import re
import subprocess
import sys
import time
import traceback
import urllib.parse
from pathlib import Path

try:
    import requests
    import yaml
except ImportError as exc:  # pragma: no cover
    print(f"api-verify: missing dependency ({exc}); pip install requests pyyaml", file=sys.stderr)
    sys.exit(2)

MODULE = "__MOD__"
SCRIPT = Path(__file__).resolve()
HTTP_METHODS = ("get", "post", "put", "patch", "delete")


# ═════════════════════════════════════════════════════════════════════════════
# config
# ═════════════════════════════════════════════════════════════════════════════
def find_repo_root() -> Path | None:
    for parent in SCRIPT.parents:
        if (parent / "scripts" / "gov-module.py").is_file():
            return parent
    return None


def load_plan(args) -> dict:
    """The v7 consumer contract, read through the one tool — never a typed path."""
    if args.plan_json:
        return json.loads(Path(args.plan_json).read_text())
    root = find_repo_root()
    if root is None:
        raise SystemExit("api-verify: scripts/gov-module.py not found above the script; pass --plan-json")
    out = subprocess.run(
        [sys.executable, str(root / "scripts" / "gov-module.py"), "--track", "backend", "plan", MODULE, "--json"],
        cwd=str(root), capture_output=True, text=True)
    if out.returncode != 0:
        raise SystemExit(f"api-verify: gov-module.py plan {MODULE} refused:\n{out.stderr or out.stdout}")
    return json.loads(out.stdout)


def build_arg_parser(extra_args):
    ap = argparse.ArgumentParser(description=f"api-verify — {MODULE} (Dev/Test only)")
    ap.add_argument("--base-url", default=None,
                    help="service base URL; default = the api-docs' first server")
    ap.add_argument("--env", required=True, choices=["dev", "test"],
                    help="the target environment class — the script refuses anything else")
    ap.add_argument("--namespace", default=None, help="run namespace for free values (default RUN-<UTC timestamp>)")
    ap.add_argument("--approval-stub-url", default=None,
                    help="Dev/Test stub of the host Approval API; without it no approval-enabled decision is exercised")
    ap.add_argument("--log-file", default=None, help="service log for approximate correlation (default logs/aias-local.log)")
    ap.add_argument("--check-timeout", type=float, default=120.0,
                    help="seconds to poll an asynchronous Check (aias.check.timeout, default PT2M)")
    ap.add_argument("--http-timeout", type=float, default=30.0)
    ap.add_argument("--report", default=None, help="problems report path (default <script dir>/<mod>_problems_report.md)")
    ap.add_argument("--plan-json", default=None, help="a saved `gov-module.py plan --json` output")
    for flags, kw in extra_args:
        ap.add_argument(*flags, **kw)
    return ap


def confirm_dev_test(base_url: str, env: str):
    host = (urllib.parse.urlparse(base_url).hostname or "").lower()
    if host in ("localhost", "127.0.0.1", "::1") or re.search(r"(^|[.-])(dev|test|local)(\d*)([.-]|$)", host):
        return True, f"host '{host}' accepted as a {env} target"
    return False, f"refusing {base_url}: host '{host}' cannot be confirmed as a Dev/Test target"


# ═════════════════════════════════════════════════════════════════════════════
# contract — the API document (OpenAPI 3.1) and a minimal schema validator
# ═════════════════════════════════════════════════════════════════════════════
class Contract:
    def __init__(self, spec_path: str):
        self.path = spec_path
        self.spec = yaml.safe_load(Path(spec_path).read_text())
        self.ops: dict[str, dict] = {}
        for path, item in (self.spec.get("paths") or {}).items():
            for method, op in item.items():
                if method in HTTP_METHODS and isinstance(op, dict):
                    self.ops[op.get("x-api-id")] = {"method": method.upper(), "path": path, "op": op}

    def op(self, api_id):
        return self.ops[api_id]

    def responses(self, api_id) -> dict:
        return self.ops[api_id]["op"].get("responses") or {}

    def success_status(self, api_id) -> int:
        return int(next(s for s in self.responses(api_id) if str(s).startswith("2")))

    def codes(self, api_id, status) -> list:
        return list((self.responses(api_id).get(str(status)) or {}).get("x-error-codes") or [])

    def response_schema(self, api_id, status, ctype):
        content = (self.responses(api_id).get(str(status)) or {}).get("content") or {}
        return (content.get(ctype) or {}).get("schema")

    def request_schema(self, api_id):
        body = self.ops[api_id]["op"].get("requestBody") or {}
        for ctype, c in (body.get("content") or {}).items():
            return ctype, self.resolve(c.get("schema") or {})
        return None, None

    def resolve(self, schema):
        seen = 0
        while isinstance(schema, dict) and "$ref" in schema and seen < 20:
            ref = schema["$ref"]
            node = self.spec
            for part in ref.lstrip("#/").split("/"):
                node = node[part]
            schema = node
            seen += 1
        return schema

    def top_fields(self, schema) -> set:
        schema = self.resolve(schema or {})
        if schema.get("type") == "array":
            schema = self.resolve(schema.get("items") or {})
        return set((schema.get("properties") or {}).keys())

    # -- validation ---------------------------------------------------------
    _PY = {"null": (type(None),), "string": (str,), "boolean": (bool,), "array": (list,), "object": (dict,),
           "integer": (int,), "number": (int, float)}

    def validate(self, schema, value, where="$") -> list:
        errs: list[str] = []
        self._v(self.resolve(schema or {}), value, where, errs)
        return errs

    def _v(self, schema, value, where, errs):
        schema = self.resolve(schema)
        if not isinstance(schema, dict) or not schema:
            return
        if "oneOf" in schema:
            matches = sum(1 for alt in schema["oneOf"] if not self.validate(alt, value, where))
            if matches != 1:
                errs.append(f"{where}: matches {matches} of the oneOf alternatives (expected exactly 1)")
            return
        types = schema.get("type")
        types = types if isinstance(types, list) else ([types] if types else [])
        if types:
            ok = False
            for t in types:
                py = self._PY.get(t, ())
                if isinstance(value, py) and not (t in ("integer", "number") and isinstance(value, bool)):
                    ok = True
                    break
            if not ok:
                errs.append(f"{where}: expected type {'|'.join(types)}, got {type(value).__name__}")
                return
        if value is None:
            return
        if "enum" in schema and value not in schema["enum"]:
            errs.append(f"{where}: value {value!r} not in enum {schema['enum']}")
        if isinstance(value, str):
            if "maxLength" in schema and len(value) > schema["maxLength"]:
                errs.append(f"{where}: length {len(value)} > maxLength {schema['maxLength']}")
            if "pattern" in schema and not re.search(schema["pattern"], value):
                errs.append(f"{where}: {value!r} does not match pattern {schema['pattern']}")
            if schema.get("format") == "date-time":
                try:
                    dt.datetime.fromisoformat(value.replace("Z", "+00:00"))
                except ValueError:
                    errs.append(f"{where}: {value!r} is not a date-time")
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            if "minimum" in schema and value < schema["minimum"]:
                errs.append(f"{where}: {value} < minimum {schema['minimum']}")
        if isinstance(value, list):
            if "maxItems" in schema and len(value) > schema["maxItems"]:
                errs.append(f"{where}: {len(value)} items > maxItems {schema['maxItems']}")
            for i, item in enumerate(value):
                self._v(schema.get("items") or {}, item, f"{where}[{i}]", errs)
        if isinstance(value, dict):
            for req in schema.get("required") or []:
                if req not in value:
                    errs.append(f"{where}: required property '{req}' is missing")
            props = schema.get("properties") or {}
            for k, v in value.items():
                if k in props:
                    self._v(props[k], v, f"{where}.{k}", errs)
                elif schema.get("additionalProperties") is False:
                    errs.append(f"{where}: undeclared property '{k}'")


# ═════════════════════════════════════════════════════════════════════════════
# api-docs — the delivered surface (stage A inventory + pairing)
# ═════════════════════════════════════════════════════════════════════════════
def _table_after(body: str, heading_re: str) -> list[list[str]]:
    m = re.search(heading_re, body)
    if not m:
        return []
    rows, started = [], False
    for line in body[m.end():].splitlines():
        if line.startswith("|"):
            started = True
            cells = [c.strip() for c in line.strip().strip("|").split("|")]
            if set("".join(cells)) <= set("-: "):
                continue
            rows.append(cells)
        elif started and line.strip() == "":
            break
        elif started:
            break
        elif line.startswith("#"):
            break
    return rows[1:] if rows else []


def parse_api_docs(api_docs_dir: str):
    root = Path(api_docs_dir)
    servers, endpoints = [], []
    index = root / "index.md"
    if index.is_file():
        m = re.search(r"## Servers\s*\n+((?:- \S+\s*\n?)+)", index.read_text())
        servers = re.findall(r"- (\S+)", m.group(1)) if m else []
    for f in sorted((root / "endpoints").glob("*.md")) if (root / "endpoints").is_dir() else []:
        parts = re.split(r"(?m)^## (GET|POST|PUT|PATCH|DELETE) (\S+)\s*$", f.read_text())
        for i in range(1, len(parts), 3):
            method, path, body = parts[i], parts[i + 1], parts[i + 2]
            cid = re.search(r"Contract ID: `([^`]+)`", body)
            resp = re.findall(r"### Response `(\d{3})`", body)
            resp_fields = {r[0] for r in _table_after(body, r"### Response `\d{3}`[^\n]*\n") if r and "." not in r[0] and "[]" not in r[0]}
            req_fields = {r[0] for r in _table_after(body, r"### Request Body[^\n]*\n") if r and "." not in r[0] and "[]" not in r[0]}
            query = {r[0]: (r[2].lower() == "yes") for r in _table_after(body, r"### Query Parameters[^\n]*\n") if len(r) >= 3}
            endpoints.append({"method": method, "path": path, "contract_id": cid.group(1) if cid else None,
                              "responses": [int(x) for x in resp], "resp_fields": resp_fields,
                              "req_fields": req_fields, "query": query, "file": f.name})
    return servers, endpoints


def pair_surface(contract: Contract, endpoints: list):
    """Pair by method + path (§1); return (pairing rows, static contract-mismatch findings)."""
    rows, findings = [], []
    by_key = {(e["method"], e["path"]): e for e in endpoints}
    for api_id, o in sorted(contract.ops.items()):
        ep = by_key.get((o["method"], o["path"]))
        rows.append((api_id, o["method"], o["path"], ep["file"] if ep else "— not documented"))
        where = f"{o['method']} {o['path']}"
        if not ep:
            findings.append((api_id, where, "operation has no delivered counterpart in the api-docs (not yet served)"))
            continue
        if ep["contract_id"] != api_id:
            findings.append((api_id, where, f"api-docs carry contract id {ep['contract_id']!r}, the API document {api_id}"))
        success = contract.success_status(api_id)
        doc_success = [s for s in ep["responses"] if 200 <= s < 300]
        if doc_success and success not in doc_success:
            findings.append((api_id, where, f"api-docs document success status {doc_success}, the API document {success}"))
        spec_fields = contract.top_fields(contract.response_schema(api_id, success, "application/json"))
        if spec_fields and ep["resp_fields"] and spec_fields != ep["resp_fields"]:
            findings.append((api_id, where, "response fields differ — only in API document: "
                             f"{sorted(spec_fields - ep['resp_fields'])}; only in api-docs: {sorted(ep['resp_fields'] - spec_fields)}"))
        _, req = contract.request_schema(api_id)
        req_fields = set((req or {}).get("properties") or {})
        if req_fields and ep["req_fields"] and req_fields != ep["req_fields"]:
            findings.append((api_id, where, "request fields differ — only in API document: "
                             f"{sorted(req_fields - ep['req_fields'])}; only in api-docs: {sorted(ep['req_fields'] - req_fields)}"))
        for p in o["op"].get("parameters") or []:
            p = contract.resolve(p)
            if p.get("in") == "query" and p.get("name") in ep["query"] and bool(p.get("required")) != ep["query"][p["name"]]:
                findings.append((api_id, where, f"query parameter '{p['name']}': API document required={bool(p.get('required'))}, "
                                 f"api-docs required={ep['query'][p['name']]}"))
    spec_keys = {(o["method"], o["path"]) for o in contract.ops.values()}
    for e in endpoints:
        if (e["method"], e["path"]) not in spec_keys:
            rows.append((e["contract_id"] or "—", e["method"], e["path"], e["file"] + " (no API-document operation)"))
            findings.append((e["contract_id"] or "—", f"{e['method']} {e['path']}",
                             "delivered endpoint has no operation in the API document"))
    return rows, findings


# ═════════════════════════════════════════════════════════════════════════════
# client
# ═════════════════════════════════════════════════════════════════════════════
class Call:
    def __init__(self, method, url, request_desc, response=None, error=None, log_offset=0):
        self.method, self.url, self.request_desc, self.error, self.log_offset = method, url, request_desc, error, log_offset
        self.status = response.status_code if response is not None else None
        self.headers = dict(response.headers) if response is not None else {}
        self.ctype = (self.headers.get("Content-Type") or "").split(";")[0].strip().lower()
        self.body = None
        self.text = ""
        if response is not None:
            self.text = response.text[:4000]
            try:
                self.body = response.json()
            except ValueError:
                self.body = None

    @property
    def code(self):
        return self.body.get("code") if isinstance(self.body, dict) else None

    def safe_body(self):
        """ProblemDetail bodies verbatim; success bodies as a shape summary (no document content, G13)."""
        if self.ctype == "application/problem+json" and isinstance(self.body, dict):
            return json.dumps(self.body, ensure_ascii=False)
        if isinstance(self.body, list):
            return f"array[{len(self.body)}]" + (f" of objects with keys {sorted(self.body[0].keys())}" if self.body and isinstance(self.body[0], dict) else "")
        if isinstance(self.body, dict):
            return "object with keys " + json.dumps(sorted(self.body.keys()))
        return (self.text or "")[:300]


class Client:
    def __init__(self, base_url, http_timeout, log_file):
        self.base = base_url.rstrip("/")
        self.session = requests.Session()
        self.timeout = http_timeout
        self.log_file = Path(log_file) if log_file else None

    def log_offset(self):
        try:
            return self.log_file.stat().st_size if self.log_file else 0
        except OSError:
            return 0

    def request(self, method, path, *, params=None, json_body=None, raw=None, files=None, data=None, headers=None):
        assert method in ("GET", "POST"), "aias exposes no PUT / PATCH / DELETE — the script never calls one"
        url = self.base + path
        if params:
            url_shown = url + "?" + urllib.parse.urlencode(params)
        else:
            url_shown = url
        desc = {}
        if json_body is not None:
            desc["json"] = json_body
        if raw is not None:
            desc["raw"] = raw if isinstance(raw, str) else f"<{len(raw)} bytes>"
            if headers:
                desc["headers"] = headers
        if files:
            desc["multipart"] = {k: (f"<file {v[0]!r}, {len(v[1])} bytes synthetic>" if isinstance(v, tuple) else v)
                                 for k, v in files.items()}
            if data:
                desc["multipart"].update(data)
        off = self.log_offset()
        try:
            resp = self.session.request(method, url, params=params, json=json_body,
                                        data=raw if raw is not None else data, files=files,
                                        headers=headers, timeout=self.timeout)
            return Call(method, url_shown, desc, resp, None, off)
        except requests.RequestException as exc:
            return Call(method, url_shown, desc, None, f"{type(exc).__name__}: {exc}", off)

    def get(self, path, **kw):
        return self.request("GET", path, **kw)

    def post(self, path, **kw):
        return self.request("POST", path, **kw)

    def log_excerpt(self, call: Call, needle=None, limit=12):
        if not self.log_file:
            return [], True
        try:
            with self.log_file.open("rb") as fh:
                fh.seek(call.log_offset)
                chunk = fh.read(200_000).decode("utf-8", "replace")
        except OSError:
            return [], True
        lines = [l[:300] for l in chunk.splitlines() if re.search(r"\b(WARN|ERROR)\b|Exception", l)]
        exact = bool(needle) and any(str(needle) in l for l in lines)
        return lines[:limit], not exact


# ═════════════════════════════════════════════════════════════════════════════
# results
# ═════════════════════════════════════════════════════════════════════════════
BUCKETS = ("contract mismatch", "likely real bug", "test assumption mismatch", "infrastructure")


class Runner:
    def __init__(self, contract: Contract, client: Client, namespace: str):
        self.c, self.http, self.ns = contract, client, namespace
        self.suite = "preflight"
        self.results: list[dict] = []        # asserted
        self.observations: list[dict] = []   # stage E — never pass/fail
        self.blocked: list[dict] = []        # A0 — blocked on precondition
        self.not_exercisable: list[dict] = []
        self.untraced: list[dict] = []
        self.preflight: list[dict] = []
        self.surviving: list[dict] = []
        self.static: list[tuple] = []
        self.pairing: list[tuple] = []
        self.crash = None

    # -- bookkeeping --------------------------------------------------------
    def begin(self, suite):
        self.suite = suite
        print(f"\n▶ {suite}")

    def _add(self, name, covers, ok, expected, call: Call | None, bucket=None, taxonomy=None, actual=None, note=None,
             log_needle=None):
        actual = actual if actual is not None else (
            (f"transport error {call.error}" if call and call.error else
             f"HTTP {call.status} {call.ctype} code={call.code}") if call else "—")
        res = {"suite": self.suite, "name": name, "covers": covers, "ok": ok, "expected": expected, "actual": actual,
               "bucket": None if ok else bucket, "taxonomy": None if ok else taxonomy, "note": note,
               "call": None, "log": [], "log_approx": True}
        if call is not None:
            res["call"] = {"method": call.method, "url": call.url, "request": call.request_desc,
                           "status": call.status, "body": call.safe_body() if not call.error else call.error}
            if not ok and taxonomy != "CONTRACT_BREAK":
                res["log"], res["log_approx"] = self.http.log_excerpt(call, log_needle)
        self.results.append(res)
        print(f"  {'PASS' if ok else 'FAIL'}  {name}" + ("" if ok else f"  [{taxonomy}] expected {expected}; got {actual}"))
        return ok

    def observe(self, name, covers, call: Call, note):
        self.observations.append({"suite": self.suite, "name": name, "covers": covers, "note": note,
                                  "status": call.status, "code": call.code, "ctype": call.ctype,
                                  "url": call.url, "request": call.request_desc, "error": call.error,
                                  "body": call.safe_body() if not call.error else call.error, "log": [], "log_approx": True})
        if call.status and call.status >= 500:   # an unexplained 5xx is surfaced as a likely real bug (stage G)
            self.observations[-1]["log"], self.observations[-1]["log_approx"] = self.http.log_excerpt(call)
        print(f"  OBS   {name}: HTTP {call.status} code={call.code}")

    def block(self, item, covers, reason):
        self.blocked.append({"suite": self.suite, "item": item, "covers": covers, "reason": reason})
        print(f"  BLOCKED {item} — {reason}")

    def unexercisable(self, api_id, code, reason, tc=""):
        self.not_exercisable.append({"api": api_id, "code": code, "reason": reason, "tc": tc})

    def untraced_negative(self, api_id, code):
        self.untraced.append({"api": api_id, "code": code})

    def precondition(self, value, source, check, ok, detail, blocks):
        self.preflight.append({"value": value, "source": source, "check": check, "ok": ok, "detail": detail, "blocks": blocks})
        print(f"  {'OK  ' if ok else 'MISS'}  precondition {value!r} ({source}) — {'verified' if ok else detail}")
        return ok

    def track(self, resource, ident, service_code, request_number, what):
        self.surviving.append({"resource": resource, "id": ident, "service_code": service_code,
                               "request_number": request_number, "what": what})

    def asserted_failures(self):
        return [r for r in self.results if not r["ok"]]

    # -- assertions ---------------------------------------------------------
    def _transport(self, name, covers, call):
        return self._add(name, covers, False, "a response", call, "infrastructure", "ENVIRONMENT_FAILURE")

    def expect_success(self, name, api_id, call: Call, covers="", checks=()):
        """Assert the documented success status and the response schema; `checks` = [(label, bool, detail)]."""
        covers = covers or api_id
        if call.error:
            return self._transport(name, covers, call), None
        status = self.c.success_status(api_id)
        if call.status != status:
            if call.status and call.status >= 500:
                bucket, tax = "likely real bug", "SERVER_ERROR"
            elif call.status == 404 and call.code is None:
                bucket, tax = "contract mismatch", "MISSING_IMPLEMENTATION"
            elif call.status and 200 <= call.status < 300:
                bucket, tax = "contract mismatch", "CONTRACT_BREAK"
            else:
                bucket, tax = "likely real bug", "VALIDATION_FAILURE"
            self._add(f"{name} — HTTP {status}", covers, False, f"HTTP {status}", call, bucket, tax)
            return False, None
        ok_all = self._add(f"{name} — HTTP {status}", covers, True, f"HTTP {status}", call)
        schema = self.c.response_schema(api_id, status, "application/json")
        errs = [] if call.ctype == "application/json" else [f"Content-Type {call.ctype!r}, API document application/json"]
        if schema is not None:
            errs += self.c.validate(schema, call.body) if call.body is not None or call.ctype == "application/json" else ["no JSON body"]
        ok_all &= self._add(f"{name} — body conforms to the API document", covers, not errs,
                            "the API document's response schema", call, "contract mismatch", "CONTRACT_BREAK",
                            actual="; ".join(errs[:6]) if errs else None)
        for label, ok, detail in checks:
            ok_all &= self._add(f"{name} — {label}", covers, bool(ok), label, call, "likely real bug",
                                "BUSINESS_LOGIC_ISSUE", actual=None if ok else detail)
        return ok_all, call.body

    def expect_problem(self, name, api_id, call: Call, status: int, code: str, covers=""):
        """Stage C: assert HTTP status + ProblemDetail code (never message text), then the ProblemDetail schema."""
        if code not in self.c.codes(api_id, status):
            raise AssertionError(f"generation error: {code} is not an x-error-code of {api_id} {status}")
        covers = covers or f"{api_id} ; {code}"
        if call.error:
            return self._transport(name, covers, call)
        if call.status == status and call.code == code:
            ok = self._add(f"{name} — HTTP {status} {code}", covers, True, f"HTTP {status} code={code}", call)
            schema = self.c.response_schema(api_id, status, "application/problem+json")
            errs = [] if call.ctype == "application/problem+json" else [f"Content-Type {call.ctype!r}, API document application/problem+json"]
            if schema is not None:
                errs += self.c.validate(schema, call.body)
            ok &= self._add(f"{name} — ProblemDetail conforms to the API document", covers, not errs,
                            "ProblemDetail {type, title, status, code} (+detail)", call, "contract mismatch",
                            "CONTRACT_BREAK", actual="; ".join(errs[:6]) if errs else None)
            return ok
        documented = [int(s) for s in self.c.responses(api_id) if str(s)[0] in "45"]
        if call.status and call.status >= 500:
            bucket, tax = "likely real bug", "SERVER_ERROR"
        elif call.status and 200 <= call.status < 300:
            bucket, tax = "likely real bug", "BUSINESS_LOGIC_ISSUE"     # a documented rejection did not happen
        elif call.status == 404 and call.code is None:
            bucket, tax = "contract mismatch", "MISSING_IMPLEMENTATION"
        elif call.status not in documented:
            bucket, tax = "test assumption mismatch", "CONTRACT_BREAK"   # rejected with an undocumented status
        else:
            bucket, tax = "likely real bug", "BUSINESS_LOGIC_ISSUE"
        return self._add(f"{name} — HTTP {status} {code}", covers, False, f"HTTP {status} code={code}", call, bucket, tax)


def poll_until(read, end_states, timeout, state_of=lambda b: (b or {}).get("status")):
    """Poll a documented read until a documented end state or the per-check timeout — never a fixed sleep."""
    deadline, wait, last = time.monotonic() + timeout, 0.25, None
    while True:
        last = read()
        if last.error is None and last.status == 200 and state_of(last.body) in end_states:
            return last, True
        if time.monotonic() >= deadline:
            return last, False
        time.sleep(min(wait, max(0.0, deadline - time.monotonic())))
        wait = min(wait * 2, 3.0)


