# report
# ═════════════════════════════════════════════════════════════════════════════
def _md(s):
    return str(s).replace("|", "\\|").replace("\n", " ")


def write_report(path: Path, r: Runner, meta: dict, exit_code: int):
    fails = r.asserted_failures()
    L = []
    L.append(f"# {MODULE} — API verification problems report")
    L.append("")
    L.append(f"_Generated by `{SCRIPT.name}` (api-verify skill). Dev/Test only. Run namespace `{r.ns}`._")
    L.append("")
    L.append("## Run")
    L.append("")
    for k, v in meta.items():
        L.append(f"- **{k}**: {v}")
    L.append(f"- **Result**: {'PASS' if exit_code == 0 else 'FAIL'} (exit {exit_code}) — "
             f"{len(r.results) - len(fails)} asserted checks passed, {len(fails)} failed; "
             f"{len(r.observations)} observations; {len(r.blocked)} blocked on precondition; "
             f"{len(r.not_exercisable)} not exercisable")
    if r.crash:
        L.append(f"- **Script crash** (TEST_STRUCTURE_FAILURE): `{_md(r.crash.splitlines()[-1])}`")
    L.append("")

    L.append("## Preconditions (stage A0)")
    L.append("")
    if r.preflight:
        L.append("| Value | Supplied by | Verified through | Result | Blocks |")
        L.append("|---|---|---|---|---|")
        for p in r.preflight:
            L.append(f"| `{_md(p['value'])}` | {_md(p['source'])} | {_md(p['check'])} | "
                     f"{'verified' if p['ok'] else 'NOT MET — ' + _md(p['detail'])} | {_md(p['blocks'])} |")
    else:
        L.append("No externally-owned value is referenced.")
    L.append("")

    L.append("## Inventory and pairing (stage A)")
    L.append("")
    L.append("| API id | Method | Path | api-docs |")
    L.append("|---|---|---|---|")
    for row in r.pairing:
        L.append("| " + " | ".join(_md(x) for x in row) + " |")
    L.append("")

    L.append("## Problems")
    L.append("")
    if not fails and not r.static and not r.crash and not any(o["status"] and o["status"] >= 500 for o in r.observations):
        L.append("No failure.")
    for bucket in BUCKETS:
        items = [f for f in fails if f["bucket"] == bucket]
        static = r.static if bucket == "contract mismatch" else []
        obs5 = [o for o in r.observations if o["status"] and o["status"] >= 500] if bucket == "likely real bug" else []
        if not items and not static and not obs5:
            continue
        L.append(f"### {bucket.capitalize()}")
        L.append("")
        for f in items:
            c = f["call"] or {}
            L.append(f"- **[{f['taxonomy']}] {_md(f['name'])}** — `{_md(f['covers'])}` (suite `{f['suite']}`)")
            if c:
                L.append(f"  - Request: `{c['method']} {_md(c['url'])}`" + (f" body `{_md(json.dumps(c['request'], ensure_ascii=False))}`" if c.get("request") else ""))
            L.append(f"  - Expected: {_md(f['expected'])}")
            L.append(f"  - Actual: {_md(f['actual'])}")
            if c and c.get("body"):
                L.append(f"  - Response: `{_md(c['body'])[:600]}`")
            if f["log"]:
                L.append(f"  - Log ({'approximate' if f['log_approx'] else 'correlated'}):")
                L.append("    ```")
                L.extend("    " + ln for ln in f["log"])
                L.append("    ```")
        if bucket == "likely real bug":
            for o in [o for o in r.observations if o["status"] and o["status"] >= 500]:
                L.append(f"- **[SERVER_ERROR] {_md(o['name'])}** — `{_md(o['covers'])}` (suite `{o['suite']}`; observed in "
                         "stage E — not asserted, does not affect the exit code)")
                L.append(f"  - Request: `{_md(o['url'])}` `{_md(json.dumps(o['request'], ensure_ascii=False))}`")
                L.append(f"  - Expected: a 4xx refusal (no documented outcome; {_md(o['note'])})")
                L.append(f"  - Actual: HTTP {o['status']} code={o['code']}")
                L.append(f"  - Response: `{_md(o['body'])[:600]}`")
                if o["log"]:
                    L.append(f"  - Log ({'approximate' if o['log_approx'] else 'correlated'}):")
                    L.append("    ```")
                    L.extend("    " + ln for ln in o["log"])
                    L.append("    ```")
        if static:
            L.append("- **Static (api-docs vs API document — not runtime-asserted, does not affect the exit code):**")
            for api_id, where, what in static:
                L.append(f"  - [CONTRACT_BREAK] `{api_id}` `{where}` — {_md(what)}")
        L.append("")
    if r.crash:
        L.append("### Script failure")
        L.append("")
        L.append("```")
        L.append(r.crash[-3000:])
        L.append("```")
        L.append("")

    L.append("## Blocked on precondition")
    L.append("")
    if r.blocked:
        L.append("| Suite | Item | Covers | Reason |")
        L.append("|---|---|---|---|")
        for b in r.blocked:
            L.append(f"| {b['suite']} | {_md(b['item'])} | {_md(b['covers'])} | {_md(b['reason'])} |")
    else:
        L.append("None.")
    L.append("")

    L.append("## Not exercisable")
    L.append("")
    if r.not_exercisable:
        L.append("| API id | Code | TC | Reason |")
        L.append("|---|---|---|---|")
        for n in r.not_exercisable:
            L.append(f"| {n['api']} | `{n['code']}` | {n['tc'] or '—'} | {_md(n['reason'])} |")
    else:
        L.append("None.")
    L.append("")

    L.append("## Untraced negatives")
    L.append("")
    L.append("Asserted negatives with no TC in the test plan naming the same operation and code (tagged with the code only).")
    L.append("")
    if r.untraced:
        for u in r.untraced:
            L.append(f"- `{u['api']}` · `{u['code']}`")
    else:
        L.append("None.")
    L.append("")

    L.append("## Observations (stage E — never pass/fail)")
    L.append("")
    if r.observations:
        L.append("| Suite | Scenario | Covers | Request | Observed | Note |")
        L.append("|---|---|---|---|---|---|")
        for o in r.observations:
            obs = o["error"] or f"HTTP {o['status']} {o['ctype']} code={o['code']}"
            L.append(f"| {o['suite']} | {_md(o['name'])} | {_md(o['covers'])} | `{_md(o['url'])}` | {_md(obs)} | {_md(o['note'])} |")
    else:
        L.append("None.")
    L.append("")

    L.append("## Suites")
    L.append("")
    suites = []
    for res in r.results:
        if res["suite"] not in suites:
            suites.append(res["suite"])
    for s in suites:
        rs = [x for x in r.results if x["suite"] == s]
        L.append(f"### {s} — {sum(x['ok'] for x in rs)}/{len(rs)} passed")
        L.append("")
        L.append("| Result | Check | Covers |")
        L.append("|---|---|---|")
        for x in rs:
            L.append(f"| {'PASS' if x['ok'] else 'FAIL'} | {_md(x['name'])} | {_md(x['covers'])} |")
        L.append("")

    L.append("## Surviving records")
    L.append("")
    if r.surviving:
        L.append("aias exposes no update or delete operation; these records remain in the Dev/Test schema until the "
                 "service's own retention purge removes them. A purge is a human's decision — none was executed.")
        L.append("")
        L.append("| Resource | Id | Service code | Request number | Created by |")
        L.append("|---|---|---|---|---|")
        for s in r.surviving:
            L.append(f"| {s['resource']} | {s['id']} | `{_md(s['service_code'])}` | `{_md(s['request_number'])}` | {_md(s['what'])} |")
    else:
        L.append("The tracked-id set is empty: no call of this run created a record.")
    L.append("")
    path.write_text("\n".join(L) + "\n")


# ═════════════════════════════════════════════════════════════════════════════
# main
# ═════════════════════════════════════════════════════════════════════════════
def run(extra_args, preflight, suites):
    args = build_arg_parser(extra_args).parse_args()
    plan = load_plan(args)
    for key in ("api_spec", "api_docs", "test_plan", "delivered_version", "state_file"):
        if not plan.get(key):
            print(f"api-verify: plan.{key} missing — STOP", file=sys.stderr)
            return 2
    if not Path(plan["api_spec"]).is_file():
        print("api-verify: no API document (plan.api_spec) — there is no contract to hold the docs to. STOP", file=sys.stderr)
        return 2
    if not (Path(plan["api_docs"]) / "index.md").is_file():
        print("api-verify: no generated api-docs (index.md) — run /generate-api-docs first. STOP", file=sys.stderr)
        return 2
    contract = Contract(plan["api_spec"])
    servers, endpoints = parse_api_docs(plan["api_docs"])
    base_url = args.base_url or (servers[0] if servers else "http://localhost:7271")
    ok, why = confirm_dev_test(base_url, args.env)
    print(f"api-verify {MODULE} · {why}")
    if not ok:
        print(f"api-verify: {why}", file=sys.stderr)
        return 2
    root = find_repo_root()
    log_file = args.log_file or (str(root / "logs" / "aias-local.log") if root and (root / "logs" / "aias-local.log").is_file() else None)
    namespace = args.namespace or "RUN-" + dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    report = Path(args.report) if args.report else SCRIPT.parent / f"{MODULE.lower()}_problems_report.md"
    catalog = Path(plan.get("exec_packages") or "") / "_SECTIONS.md"
    r = Runner(contract, Client(base_url, args.http_timeout, log_file), namespace)
    r.pairing, r.static = pair_surface(contract, endpoints)
    started = dt.datetime.now().astimezone().isoformat(timespec="seconds")
    meta = {
        "Module / delivered version": f"{MODULE} v{plan['delivered_version']}",
        "Target": f"{base_url} (--env {args.env})",
        "Started": started,
        "API document": f"`{plan['api_spec']}`",
        "api-docs": f"`{plan['api_docs']}` ({len(endpoints)} endpoints)",
        "Test plan": f"`{plan['test_plan']}`",
        "Error catalog": f"`{catalog}` (error-catalog block)",
        "Approval stub": args.approval_stub_url or "none given — no approval-enabled decision is exercised",
        "Log correlation": f"`{log_file}`" if log_file else "no log file",
    }
    print("inputs: " + "; ".join(f"{k}={v}" for k, v in meta.items()))
    exit_code = 1
    try:
        r.begin("preflight")
        ctx = preflight(r, args, contract)
        for suite in suites:
            r.begin(suite.__name__)
            suite(r, ctx)
    except Exception:  # the report is still written (finally)
        r.crash = traceback.format_exc()
        print(r.crash, file=sys.stderr)
    finally:
        exit_code = 0 if not r.asserted_failures() and not r.crash else 1
        meta["Ended"] = dt.datetime.now().astimezone().isoformat(timespec="seconds")
        write_report(report, r, meta, exit_code)
        fails = r.asserted_failures()
        print(f"\n{MODULE}: {'PASS' if exit_code == 0 else 'FAIL'} — {len(r.results) - len(fails)} passed, "
              f"{len(fails)} failed, {len(r.observations)} observations, {len(r.blocked)} blocked, "
              f"{len(r.not_exercisable)} not exercisable, {len(r.surviving)} surviving records → {report}")
    return exit_code


